  Example build.zig.

  ```zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const quix = b.dependency("quix", .{
        .target = target,
        .optimize = optimize,
    });

    const app_mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });
    app_mod.addImport("quix", quix.module("quix"));

    const app = b.addExecutable(.{
        .name = "my_app",
        .root_module = app_mod,
    });

    b.installArtifact(app);

    const run_cmd = b.addRunArtifact(app);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| {
        run_cmd.addArgs(args);
    }

    const run_step = b.step("run", "Run the app");
    run_step.dependOn(&amp;run_cmd.step);

    const exe_unit_tests = b.addTest(.{ .root_module = app_mod });
    const run_exe_unit_tests = b.addRunArtifact(exe_unit_tests);

    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&amp;run_exe_unit_tests.step);
}
  ```



