    return err;
};

defer conn.deinit();

var result = try conn.exec(@constCast("CREATE TABLE test (id Int32) engine=MergeTree() order by id;"), .{});

std.debug.print("{d}\n", .{result.affectedRows()});

result = try conn.exec(@constCast("INSERT INTO test values ({i}),({i}),({i})"), .{1,2,3});

